import type { ExportedFlow, RecorderSession } from "./schema";
import { enrichAllSteps } from "./step-inference";
import { normalizeStepScope } from "./step-scope";

export const makeSessionId = (): string => {
  const cryptoId = crypto.randomUUID?.();
  return cryptoId ?? `session-${Date.now()}-${Math.random().toString(16).slice(2)}`;
};

export const getBrowserName = (): ExportedFlow["session"]["browser"] => {
  const userAgent = navigator.userAgent.toLowerCase();

  if (userAgent.includes("edg/")) {
    return "edge";
  }

  if (userAgent.includes("chrome/") || userAgent.includes("chromium/")) {
    return "chrome";
  }

  return "unknown";
};

export const createExportPayload = (session: RecorderSession): ExportedFlow => ({
  schemaVersion: "1.0.0",
  session: {
    id: session.id,
    startedAt: session.startedAt,
    endedAt: session.endedAt,
    browser: getBrowserName(),
    startUrl: session.startUrl,
    tabTitle: session.tabTitle
  },
  video: session.video,
  steps: enrichAllSteps(session.id, session.steps).map(normalizeStepScope)
});

export const downloadBlob = (blob: Blob, fileName: string): void => {
  const url = URL.createObjectURL(blob);
  const anchor = document.createElement("a");
  anchor.href = url;
  anchor.download = fileName;
  anchor.click();
  URL.revokeObjectURL(url);
};

export const formatDuration = (durationMs: number): string => {
  const seconds = Math.floor(durationMs / 1000);
  const minutes = Math.floor(seconds / 60);
  const restSeconds = seconds % 60;
  return `${minutes.toString().padStart(2, "0")}:${restSeconds.toString().padStart(2, "0")}`;
};
