import type { FlowStep } from "./schema";

/** Canonical scope fields for a recorded/replayed step. */
export const normalizeStepScope = (step: FlowStep): FlowStep => {
  const frameId = step.frameId ?? 0;
  const isTopFrame = step.isTopFrame ?? frameId === 0;
  const topUrl = step.topUrl ?? (isTopFrame ? step.url : undefined);

  if (!isTopFrame && frameId !== 0) {
    return {
      ...step,
      frameId,
      isTopFrame: false,
      topUrl,
      frameUrl: step.frameUrl ?? step.url
    };
  }

  return {
    ...step,
    frameId: 0,
    isTopFrame: true,
    topUrl,
    frameUrl: topUrl
  };
};

export const getStepTopUrl = (step: FlowStep): string | undefined =>
  step.topUrl ?? (step.isTopFrame === false ? undefined : step.url);

/** Only iframe steps need a frame document URL; top-frame steps use topUrl instead. */
export const getStepFrameUrl = (step: FlowStep): string | undefined => {
  if ((step.frameId ?? 0) === 0 || step.isTopFrame !== false) {
    return undefined;
  }

  return step.frameUrl ?? step.url;
};
