import type { FlowStep, PostCondition } from "./schema";
import { getStepTopUrl, normalizeStepScope } from "./step-scope";
import { urlsMatchForReplay } from "./url";

const DEFAULT_TOP_URL_TIMEOUT_MS = 12_000;
const DEFAULT_FRAME_URL_TIMEOUT_MS = 10_000;
const DEFAULT_POPUP_TIMEOUT_MS = 8_000;
const MIN_TAB_TRANSITION_WAIT_MS = 800;
const MAX_TAB_TRANSITION_WAIT_MS = 12_000;
const DEFAULT_NEW_TAB_SELECTOR_TIMEOUT_MS = 15_000;

export const POPUP_CONTAINER_SELECTORS = [
  ".el-overlay-message-box",
  ".el-dialog",
  ".el-drawer",
  ".ant-modal-wrap",
  ".ant-modal",
  ".van-dialog",
  ".van-popup--show",
  "[role='dialog']",
  "[aria-modal='true']"
].join(", ");

const mergePostCondition = (
  existing: PostCondition | PostCondition[] | undefined,
  incoming: PostCondition
): PostCondition | PostCondition[] => {
  if (!existing) {
    return incoming;
  }

  const list = Array.isArray(existing) ? [...existing] : [existing];
  const duplicate = list.some((item) => item.type === incoming.type && item.value === incoming.value);
  if (!duplicate) {
    list.push(incoming);
  }

  return list.length === 1 ? list[0] : list;
};

const suggestsPopupTarget = (step: FlowStep): boolean => {
  const selector = step.target?.selector ?? "";
  const role = step.target?.role ?? step.target?.attributes?.role ?? "";
  return (
    role === "dialog" ||
    /dialog|modal|popup|message-box|drawer/i.test(selector) ||
    /dialog|modal|popup/i.test(step.target?.tagName ?? "")
  );
};

export const createNavigateStep = (sessionId: string, stepIndex: number, template: FlowStep, navigateUrl: string): FlowStep =>
  normalizeStepScope({
    id: `${sessionId}-step-${stepIndex + 1}`,
    type: "navigate",
    timestampMs: template.timestampMs,
    url: navigateUrl,
    navigateUrl,
    tabId: template.tabId,
    frameId: 0,
    isTopFrame: true
  });

const estimateTabTransitionWaitMs = (previous: FlowStep, next: FlowStep): number => {
  const delta = Math.max(next.timestampMs - previous.timestampMs, MIN_TAB_TRANSITION_WAIT_MS);
  return Math.min(delta, MAX_TAB_TRANSITION_WAIT_MS);
};

const pickReadySelector = (step: FlowStep): string | undefined => {
  if (!step.target || !["input", "change", "click"].includes(step.type)) {
    return undefined;
  }

  return step.target.selector ?? step.target.selectorCandidates[0];
};

export const createWaitStepForNewTab = (
  sessionId: string,
  stepIndex: number,
  template: FlowStep,
  waitMs: number,
  readySelector?: string
): FlowStep => {
  const topUrl = getStepTopUrl(template) ?? template.url;

  return normalizeStepScope({
    id: `${sessionId}-step-${stepIndex + 1}`,
    type: "wait",
    timestampMs: template.timestampMs,
    url: topUrl,
    topUrl,
    tabId: template.tabId,
    frameId: 0,
    isTopFrame: true,
    waitMs,
    postCondition: readySelector
      ? { type: "selector", value: readySelector, timeoutMs: DEFAULT_NEW_TAB_SELECTOR_TIMEOUT_MS }
      : undefined
  });
};

/** Re-run step enrichment on a full list (export / replay preparation). */
export const enrichAllSteps = (sessionId: string, steps: FlowStep[]): FlowStep[] => {
  let result: FlowStep[] = [];

  for (const step of steps.map(normalizeStepScope)) {
    if (!result.length) {
      result.push(step);
      continue;
    }

    result = enrichStepsBeforePush(sessionId, result, step);
  }

  return result;
};

/** Insert navigate steps and postConditions when top/frame/popup context changes. */
export const enrichStepsBeforePush = (
  sessionId: string,
  steps: FlowStep[],
  incoming: FlowStep
): FlowStep[] => {
  const normalized = normalizeStepScope(incoming);
  const previous = steps.at(-1);

  if (!previous || previous.type === "navigate" || previous.type === "postmessage" || previous.type === "wait") {
    return [...steps, normalized];
  }

  const result = [...steps];
  let previousIndex = result.length - 1;
  let previousStep = result[previousIndex];

  const sameTab = (previousStep.tabId ?? 0) === (normalized.tabId ?? 0);
  const prevTop = getStepTopUrl(previousStep);
  const nextTop = getStepTopUrl(normalized);

  if (sameTab && prevTop && nextTop && !urlsMatchForReplay(prevTop, nextTop)) {
    previousStep = {
      ...previousStep,
      postCondition: mergePostCondition(previousStep.postCondition, {
        type: "topUrl",
        value: nextTop,
        timeoutMs: DEFAULT_TOP_URL_TIMEOUT_MS
      })
    };
    result[previousIndex] = previousStep;

    result.push(createNavigateStep(sessionId, result.length, normalized, nextTop));
    return [...result, normalized];
  }

  if (
    sameTab &&
    previousStep.isTopFrame !== false &&
    normalized.isTopFrame === false &&
    normalized.frameUrl &&
    !urlsMatchForReplay(previousStep.frameUrl, normalized.frameUrl)
  ) {
    previousStep = {
      ...previousStep,
      postCondition: mergePostCondition(previousStep.postCondition, {
        type: "frameUrl",
        value: normalized.frameUrl,
        timeoutMs: DEFAULT_FRAME_URL_TIMEOUT_MS
      })
    };
    result[previousIndex] = previousStep;
  }

  if (
    (previousStep.type === "click" || previousStep.type === "submit") &&
    suggestsPopupTarget(normalized)
  ) {
    previousStep = {
      ...previousStep,
      postCondition: mergePostCondition(previousStep.postCondition, {
        type: "popup",
        timeoutMs: DEFAULT_POPUP_TIMEOUT_MS
      })
    };
    result[previousIndex] = previousStep;
  }

  if (
    !sameTab &&
    (previousStep.type === "click" || previousStep.type === "submit") &&
    normalized.tabId !== undefined
  ) {
    const waitMs = estimateTabTransitionWaitMs(previousStep, normalized);
    const readySelector = pickReadySelector(normalized);

    previousStep = {
      ...previousStep,
      opensTabId: normalized.tabId
    };
    result[previousIndex] = previousStep;

    result.push(createWaitStepForNewTab(sessionId, result.length, normalized, waitMs, readySelector));
    return [...result, normalized];
  }

  return [...result, normalized];
};
