import type { RecorderSession, RecordingHistoryEntry } from "./schema";
import { deleteSessionSnapshots, pruneSessionScreenshots } from "./screenshot-db";

export const HISTORY_STORAGE_KEY = "mv3Recorder.history";
export const MAX_HISTORY_ENTRIES = 3;

export const sessionToHistoryEntry = (session: RecorderSession): RecordingHistoryEntry => ({
  id: session.id,
  startedAt: session.startedAt,
  endedAt: session.endedAt,
  durationMs: session.durationMs,
  startUrl: session.startUrl,
  tabTitle: session.tabTitle,
  steps: session.steps,
  video: session.video
});

export const historyEntryToSession = (entry: RecordingHistoryEntry): RecorderSession => ({
  id: entry.id,
  status: "stopped",
  tabId: 0,
  recordedTabIds: [],
  startUrl: entry.startUrl,
  tabTitle: entry.tabTitle,
  startedAt: entry.startedAt,
  endedAt: entry.endedAt,
  durationMs: entry.durationMs,
  steps: entry.steps,
  video: entry.video
});

export const loadRecordingHistory = async (): Promise<RecordingHistoryEntry[]> => {
  const stored = await chrome.storage.local.get(HISTORY_STORAGE_KEY);
  const history = stored[HISTORY_STORAGE_KEY];

  if (!Array.isArray(history)) {
    return [];
  }

  const entries = history as RecordingHistoryEntry[];
  if (entries.length <= MAX_HISTORY_ENTRIES) {
    return entries;
  }

  const trimmed = entries.slice(0, MAX_HISTORY_ENTRIES);
  const removed = entries.slice(MAX_HISTORY_ENTRIES);
  await chrome.storage.local.set({ [HISTORY_STORAGE_KEY]: trimmed });
  await Promise.all(removed.map((entry) => deleteSessionSnapshots(entry.id)));

  return trimmed;
};

export const appendRecordingHistory = async (entry: RecordingHistoryEntry): Promise<void> => {
  const history = await loadRecordingHistory();
  const withoutDuplicate = history.filter((item) => item.id !== entry.id);
  const combined = [entry, ...withoutDuplicate];
  const next = combined.slice(0, MAX_HISTORY_ENTRIES);
  const removed = combined.slice(MAX_HISTORY_ENTRIES);

  await chrome.storage.local.set({ [HISTORY_STORAGE_KEY]: next });
  await Promise.all(removed.map((item) => deleteSessionSnapshots(item.id)));
};

export const removeRecordingHistoryEntry = async (sessionId: string): Promise<void> => {
  const history = await loadRecordingHistory();
  const next = history.filter((item) => item.id !== sessionId);
  await chrome.storage.local.set({ [HISTORY_STORAGE_KEY]: next });
  await deleteSessionSnapshots(sessionId);
};

export const clearRecordingHistory = async (keepScreenshotSessionIds: string[] = []): Promise<void> => {
  await chrome.storage.local.set({ [HISTORY_STORAGE_KEY]: [] });
  await pruneSessionScreenshots(keepScreenshotSessionIds);
};

export const formatHistoryTitle = (entry: RecordingHistoryEntry): string => {
  if (entry.tabTitle?.trim()) {
    return entry.tabTitle.trim();
  }

  try {
    return new URL(entry.startUrl).hostname;
  } catch {
    return entry.startUrl;
  }
};

export const formatHistoryTime = (isoTime: string): string => {
  const date = new Date(isoTime);

  if (Number.isNaN(date.getTime())) {
    return isoTime;
  }

  return date.toLocaleString(undefined, {
    month: "2-digit",
    day: "2-digit",
    hour: "2-digit",
    minute: "2-digit"
  });
};
