/** Query keys often used as cache-busters; ignored when comparing replay URLs. */
const VOLATILE_QUERY_KEYS = new Set([
  "_t",
  "_",
  "t",
  "ts",
  "timestamp",
  "time",
  "nonce",
  "cachebust",
  "cacheBust",
  "rnd",
  "random",
  "v",
  "ver"
]);

const isVolatileQueryKey = (key: string): boolean => {
  const lower = key.toLowerCase();
  if (VOLATILE_QUERY_KEYS.has(lower)) {
    return true;
  }

  return lower.endsWith("timestamp") || lower.includes("nonce");
};

/** Normalize URL for stable comparison (SPA / iframe / replay navigation). */
export const normalizeUrlForComparison = (rawUrl: string): string => {
  try {
    const url = new URL(rawUrl);
    const kept = new URLSearchParams();

    url.searchParams.forEach((value, key) => {
      if (!isVolatileQueryKey(key)) {
        kept.append(key, value);
      }
    });

    kept.sort();
    const query = kept.toString();
    return `${url.origin}${url.pathname}${query ? `?${query}` : ""}${url.hash}`;
  } catch {
    return rawUrl.split("#")[0]?.split("?")[0] ?? rawUrl;
  }
};

export const urlsMatchForReplay = (left: string | undefined, right: string | undefined): boolean => {
  if (!left || !right) {
    return false;
  }

  return normalizeUrlForComparison(left) === normalizeUrlForComparison(right);
};
