/** Relative path of a step screenshot inside an export bundle. */
export const getScreenshotRelativePath = (stepId: string): string => `screenshots/${stepId}.png`;

export const getScreenshotFileName = (stepId: string): string => `${stepId}.png`;

export const dataUrlToBase64 = (dataUrl: string): string => {
  const commaIndex = dataUrl.indexOf(",");
  return commaIndex >= 0 ? dataUrl.slice(commaIndex + 1) : dataUrl;
};
