const DB_NAME = "mv3Recorder";
const DB_VERSION = 2;
const STORE_NAME = "screenshots";
const HTML_STORE_NAME = "html";

const makeStorageKey = (sessionId: string, stepId: string): string => `${sessionId}:${stepId}`;

const openDatabase = (): Promise<IDBDatabase> =>
  new Promise((resolve, reject) => {
    const request = indexedDB.open(DB_NAME, DB_VERSION);

    request.onerror = () => reject(request.error ?? new Error("无法打开截图数据库。"));
    request.onsuccess = () => resolve(request.result);
    request.onupgradeneeded = () => {
      const database = request.result;
      if (!database.objectStoreNames.contains(STORE_NAME)) {
        database.createObjectStore(STORE_NAME);
      }
      if (!database.objectStoreNames.contains(HTML_STORE_NAME)) {
        database.createObjectStore(HTML_STORE_NAME);
      }
    };
  });

export const saveSessionScreenshot = async (
  sessionId: string,
  stepId: string,
  dataUrl: string
): Promise<void> => {
  const database = await openDatabase();

  await new Promise<void>((resolve, reject) => {
    const transaction = database.transaction(STORE_NAME, "readwrite");
    const store = transaction.objectStore(STORE_NAME);
    store.put(dataUrl, makeStorageKey(sessionId, stepId));
    transaction.oncomplete = () => resolve();
    transaction.onerror = () => reject(transaction.error ?? new Error("保存截图失败。"));
  });
};

export const getSessionScreenshots = async (sessionId: string): Promise<Record<string, string>> => {
  const database = await openDatabase();
  const prefix = `${sessionId}:`;
  const screenshots: Record<string, string> = {};

  await new Promise<void>((resolve, reject) => {
    const transaction = database.transaction(STORE_NAME, "readonly");
    const store = transaction.objectStore(STORE_NAME);
    const request = store.openCursor();

    request.onerror = () => reject(request.error ?? new Error("读取截图失败。"));
    request.onsuccess = () => {
      const cursor = request.result;
      if (!cursor) {
        return;
      }

      const key = String(cursor.key);
      if (key.startsWith(prefix)) {
        screenshots[key.slice(prefix.length)] = String(cursor.value);
      }

      cursor.continue();
    };

    transaction.oncomplete = () => resolve();
    transaction.onerror = () => reject(transaction.error ?? new Error("读取截图事务失败。"));
  });

  return screenshots;
};

const deleteScreenshotKeys = async (keys: string[]): Promise<void> => {
  if (!keys.length) {
    return;
  }

  const database = await openDatabase();

  await new Promise<void>((resolve, reject) => {
    const transaction = database.transaction(STORE_NAME, "readwrite");
    const store = transaction.objectStore(STORE_NAME);

    for (const key of keys) {
      store.delete(key);
    }

    transaction.oncomplete = () => resolve();
    transaction.onerror = () => reject(transaction.error ?? new Error("删除截图失败。"));
  });
};

export const saveSessionHtml = async (sessionId: string, stepId: string, html: string): Promise<void> => {
  const database = await openDatabase();

  await new Promise<void>((resolve, reject) => {
    const transaction = database.transaction(HTML_STORE_NAME, "readwrite");
    const store = transaction.objectStore(HTML_STORE_NAME);
    store.put(html, makeStorageKey(sessionId, stepId));
    transaction.oncomplete = () => resolve();
    transaction.onerror = () => reject(transaction.error ?? new Error("保存页面 HTML 失败。"));
  });
};

