/** Deletes screenshots and HTML snapshots for a session. */
export const deleteSessionSnapshots = async (sessionId: string): Promise<void> => {
  await deleteSessionScreenshots(sessionId);
  await deleteSessionHtml(sessionId);
};

export const remapSessionScreenshots = async (
  sessionId: string,
  beforeSteps: { id: string }[],
  afterSteps: { id: string }[]
): Promise<void> => {
  const screenshots = await getSessionScreenshots(sessionId);
  let changed = false;

  for (let index = 0; index < afterSteps.length; index += 1) {
    const oldId = beforeSteps[index]?.id;
    const newId = afterSteps[index]?.id;

    if (!oldId || !newId || oldId === newId || !screenshots[oldId]) {
      continue;
    }

    screenshots[newId] = screenshots[oldId];
    delete screenshots[oldId];
    changed = true;
  }

  if (!changed) {
    return;
  }

  await deleteSessionScreenshots(sessionId);
  await Promise.all(
    Object.entries(screenshots).map(([stepId, dataUrl]) => saveSessionScreenshot(sessionId, stepId, dataUrl))
  );
};

export const pruneSessionScreenshots = async (keepSessionIds: string[]): Promise<void> => {
  const keep = new Set(keepSessionIds);
  const database = await openDatabase();
  const keysToDelete: string[] = [];

  await new Promise<void>((resolve, reject) => {
    const transaction = database.transaction(STORE_NAME, "readonly");
    const store = transaction.objectStore(STORE_NAME);
    const request = store.openCursor();

    request.onerror = () => reject(request.error ?? new Error("枚举截图失败。"));
    request.onsuccess = () => {
      const cursor = request.result;
      if (!cursor) {
        return;
      }

      const sessionId = String(cursor.key).split(":")[0];
      if (sessionId && !keep.has(sessionId)) {
        keysToDelete.push(String(cursor.key));
      }

      cursor.continue();
    };

    transaction.oncomplete = () => resolve();
    transaction.onerror = () => reject(transaction.error ?? new Error("枚举截图事务失败。"));
  });

  await deleteScreenshotKeys(keysToDelete);
  await pruneSessionHtml(keepSessionIds);
};

export const remapSessionHtml = async (
  sessionId: string,
  beforeSteps: { id: string }[],
  afterSteps: { id: string }[]
): Promise<void> => {
  const htmlByStep = await getSessionHtml(sessionId);
  let changed = false;

  for (let index = 0; index < afterSteps.length; index += 1) {
    const oldId = beforeSteps[index]?.id;
    const newId = afterSteps[index]?.id;

    if (!oldId || !newId || oldId === newId || !htmlByStep[oldId]) {
      continue;
    }

    htmlByStep[newId] = htmlByStep[oldId];
    delete htmlByStep[oldId];
    changed = true;
  }

  if (!changed) {
    return;
  }

  await deleteSessionHtml(sessionId);
  await Promise.all(
    Object.entries(htmlByStep).map(([stepId, html]) => saveSessionHtml(sessionId, stepId, html))
  );
};

